-- The demo offers 21 of the 39 on-device voices (three models), so the Privacy Policy, Help and
-- What's new (6896) say so. Same text as src/data/legalPages.json and changelog.json; each change
-- checks what's stored first.

do $migration$
declare s text;
begin
  select sections::text into s from public.legal_pages where slug = 'privacy' for update;
  if strpos(s, $lw$"Reading aloud with a voice on your device: for books in English, members can choose from 39 natural voices (anyone trying the demo, from 21 of them) that run in your own browser, with American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents (women's, men's and a non-binary voice). A voice, about 63 to 77 MB, downloads once from our own storage (Supabase) and is kept in your browser. The text it reads never leaves your device, and nothing about your listening is sent to us or anyone else, so Kids profiles can use them too."$lw$) > 0 then return; end if;
  if strpos(s, $lw$"Reading aloud with a voice on your device: for books in English, members, and anyone trying the demo, can choose from 39 natural voices that run in your own browser, with American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents (women's, men's and a non-binary voice). A voice, about 63 to 77 MB, downloads once from our own storage (Supabase) and is kept in your browser. The text it reads never leaves your device, and nothing about your listening is sent to us or anyone else, so Kids profiles can use them too."$lw$) = 0 then raise exception 'demo voices: the privacy paragraph was not found as stored'; end if;
  update public.legal_pages set sections = replace(s, $lw$"Reading aloud with a voice on your device: for books in English, members, and anyone trying the demo, can choose from 39 natural voices that run in your own browser, with American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents (women's, men's and a non-binary voice). A voice, about 63 to 77 MB, downloads once from our own storage (Supabase) and is kept in your browser. The text it reads never leaves your device, and nothing about your listening is sent to us or anyone else, so Kids profiles can use them too."$lw$, $lw$"Reading aloud with a voice on your device: for books in English, members can choose from 39 natural voices (anyone trying the demo, from 21 of them) that run in your own browser, with American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents (women's, men's and a non-binary voice). A voice, about 63 to 77 MB, downloads once from our own storage (Supabase) and is kept in your browser. The text it reads never leaves your device, and nothing about your listening is sent to us or anyone else, so Kids profiles can use them too."$lw$)::jsonb where slug = 'privacy';
end
$migration$;

do $migration$
declare s text;
begin
  select sections::text into s from public.legal_pages where slug = 'help' for update;
  if strpos(s, $lw$"Members can also choose from 39 natural voices that run on your own device, for any book in English (the demo offers 21 of them, every accent included): American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents, women's, men's and a non-binary voice, grouped that way in the Voice menu. The first time, a voice downloads (about 63 to 77 MB); after that it starts within a few seconds and works offline. It's free, doesn't count towards your month's natural-voice reading, and the text never leaves your device. Remove the on-device voices from this device, under the Voice menu, frees the space."$lw$) > 0 then return; end if;
  if strpos(s, $lw$"Members, and anyone trying the demo, can also choose from 39 natural voices that run on your own device, for any book in English: American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents, women's, men's and a non-binary voice, grouped that way in the Voice menu. The first time, a voice downloads (about 63 to 77 MB); after that it starts within a few seconds and works offline. It's free, doesn't count towards your month's natural-voice reading, and the text never leaves your device. Remove the on-device voices from this device, under the Voice menu, frees the space."$lw$) = 0 then raise exception 'demo voices: the help paragraph was not found as stored'; end if;
  update public.legal_pages set sections = replace(s, $lw$"Members, and anyone trying the demo, can also choose from 39 natural voices that run on your own device, for any book in English: American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents, women's, men's and a non-binary voice, grouped that way in the Voice menu. The first time, a voice downloads (about 63 to 77 MB); after that it starts within a few seconds and works offline. It's free, doesn't count towards your month's natural-voice reading, and the text never leaves your device. Remove the on-device voices from this device, under the Voice menu, frees the space."$lw$, $lw$"Members can also choose from 39 natural voices that run on your own device, for any book in English (the demo offers 21 of them, every accent included): American, British, Scottish, Irish, Canadian, Australian, New Zealand and South African accents, women's, men's and a non-binary voice, grouped that way in the Voice menu. The first time, a voice downloads (about 63 to 77 MB); after that it starts within a few seconds and works offline. It's free, doesn't count towards your month's natural-voice reading, and the text never leaves your device. Remove the on-device voices from this device, under the Voice menu, frees the space."$lw$)::jsonb where slug = 'help';
end
$migration$;

update public.changelog_entries set body = $lw$The demo now has the voices that run on your device (21 of the 39, every accent included; free and offline after one download), a language for emails and log-in emails in Preferences, and a second connected app: the LiteraryWorm command line, allowed to add books and change their status.$lw$
where title = $lw$More to try in the demo$lw$ and released_on = '2026-11-28' and body = $lw$The demo now has the voices that run on your device (all 39, free and offline after one download), a language for emails and log-in emails in Preferences, and a second connected app: the LiteraryWorm command line, allowed to add books and change their status.$lw$;
